def drand48(seed):
    state = (seed << 16) | 0x330E
    a = 0x5DEECE66D
    c = 0xB
    m = 1 << 48
    while True:
        state = (a * state + c) & (m - 1)
        yield state / m

def test_prng(prng_gen, name):
    gen = prng_gen(11)
    selected = []
    for i in range(1, 101):
        # what if it generates two numbers?
        r = next(gen)
        if r < 0.05:
            selected.append(i)
    if selected == [18, 28, 40, 59]:
        print(f"Match found! {name}")
    else:
        print(f"{name}: {selected}")

test_prng(drand48, "drand48_1")

# what if it uses a 64-bit LCG?
# klib/krandom.h has a random generator?
# Heng Li's klib uses:
# uint64_t kr_rand(krng_t *r) {
#   r->z = (r->z * 2862933555777941757ULL + 3037000493ULL);
#   return r->z;
# }
def kr_rand(seed):
    z = seed
    while True:
        z = (z * 2862933555777941757 + 3037000493) & 0xFFFFFFFFFFFFFFFF
        yield z / (1<<64)

test_prng(kr_rand, "kr_rand")

# also sometimes xoroshiro or similar?
# or standard random?
def lrand48(seed):
    state = (seed << 16) | 0x330E
    a = 0x5DEECE66D
    c = 0xB
    m = 1 << 48
    while True:
        state = (a * state + c) & (m - 1)
        yield (state >> 17) / (1<<31)

test_prng(lrand48, "lrand48")

