uint64_t splitmix64() {
    uint64_t z = (state += 0x9E3779B97F4A7C15ULL);
    z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
    z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
    return z ^ (z >> 31);
}

int main() {
    state = 11;
    for (int i=1; i<=100; i++) {
        double r = (double)(splitmix64() >> 11) * 0x1.0p-53; // typical double conversion
        if (r < 0.05) printf("%d ", i);
    }
    printf("\n");
    return 0;
}
