#!/usr/bin/env python3
import sys
import os
import random
import re

def eprint(*args, **kwargs):
    print(*args, file=sys.stderr, **kwargs)

def parse_seqs(f):
    name = None
    seq = []
    qual = []
    state = 0
    seq_len = 0
    qual_len = 0
    for line in f:
        line = line.rstrip('\r\n')
        if state == 0:
            if line.startswith('>') or line.startswith('@'):
                name = line
                state = 1
        elif state == 1:
            if line.startswith('+') and name.startswith('@'):
                state = 2
            elif line.startswith('>') or line.startswith('@'):
                yield name, "".join(seq), ""
                name = line
                seq = []
                seq_len = 0
            else:
                seq.append(line)
                seq_len += len(line)
        elif state == 2:
            state = 3
            qual.append(line)
            qual_len += len(line)
            if qual_len >= seq_len:
                yield name, "".join(seq), "".join(qual)
                name = None
                seq, qual = [], []
                seq_len, qual_len = 0, 0
                state = 0
        elif state == 3:
            qual.append(line)
            qual_len += len(line)
            if qual_len >= seq_len:
                yield name, "".join(seq), "".join(qual)
                name = None
                seq, qual = [], []
                seq_len, qual_len = 0, 0
                state = 0
    if state == 1 and name:
        yield name, "".join(seq), ""
    elif state == 3 and name:
        yield name, "".join(seq), "".join(qual)

def revcomp(seq):
    trans = str.maketrans('ACGTUacgtu', 'TGCAAtgcaa')
    return seq[::-1].translate(trans)

def load_bed(f_bed):
    bed = {}
    for line in f_bed:
        if not line.strip(): continue
        parts = line.strip().split()
        if len(parts) >= 3:
            chrom = parts[0]
            start = int(parts[1])
            end = int(parts[2])
            strand = parts[5] if len(parts) >= 6 else '+'
            if chrom not in bed:
                bed[chrom] = []
            bed[chrom].append((start, end, strand))
    return bed

def mask_seq(seq, intervals, mask_char=None):
    seq_list = list(seq)
    for start, end, _ in intervals:
        start = max(0, start)
        end = min(len(seq), end)
        for i in range(start, end):
            if mask_char:
                seq_list[i] = mask_char
            else:
                seq_list[i] = seq_list[i].lower()
    return "".join(seq_list)

def get_args(args_list, fmt):
    # simplistic getopt
    opts = []
    args = []
    i = 0
    while i < len(args_list):
        arg = args_list[i]
        if arg.startswith('-') and len(arg) > 1:
            o = arg[1]
            if o in fmt:
                idx = fmt.index(o)
                if idx + 1 < len(fmt) and fmt[idx+1] == ':':
                    if len(arg) > 2:
                        opts.append(('-'+o, arg[2:]))
                    else:
                        if i + 1 < len(args_list):
                            opts.append(('-'+o, args_list[i+1]))
                            i += 1
                else:
                    for ch in arg[1:]:
                        opts.append(('-'+ch, ''))
            else:
                for ch in arg[1:]:
                    opts.append(('-'+ch, ''))
        else:
            args.append(arg)
        i += 1
    return opts, args

