    opts, args = get_args(args_list, "aQ:q:n:Cl:rM:")
    is_fasta = False
    qual_offset = 33
    qual_thresh = None
    mask_char = None
    strip_comments = False
    line_len = 0
    rev_comp = False
    mask_bed = None

    for o, a in opts:
        if o == '-a': is_fasta = True
        elif o == '-Q': qual_offset = int(a)
        elif o == '-q': qual_thresh = int(a)
        elif o == '-n': mask_char = a
        elif o == '-C': strip_comments = True
        elif o == '-l': line_len = int(a)
        elif o == '-r': rev_comp = True
        elif o == '-M':
            with open(a, 'r') as f:
                mask_bed = load_bed(f)

    if len(args) == 0:
        f_in = sys.stdin
    else:
        f_in = open(args[0], 'r')

    for name, seq, qual in parse_seqs(f_in):
