        if is_fasta or not qual:
            name = ">" + name[1:]
            print(name)
            if line_len > 0:
                for i in range(0, len(seq), line_len):
                    print(seq[i:i+line_len])
            else:
                print(seq)
        else:
            print(name)
            if line_len > 0:
                for i in range(0, len(seq), line_len):
                    print(seq[i:i+line_len])
                print("+")
                for i in range(0, len(qual), line_len):
                    print(qual[i:i+line_len])
            else:
                print(seq)
                print("+")
                print(qual)

def cmd_subseq(args_list):
    opts, args = get_args(args_list, "tsl:")
    tab_out = False
    strand_aware = False
    line_len = 0
    for o, a in opts:
        if o == '-t': tab_out = True
        elif o == '-s': strand_aware = True
        elif o == '-l': line_len = int(a)

    if len(args) < 2: return
    f_in = open(args[0], 'r')
    f_bed = open(args[1], 'r')

    is_bed = False
    first_line = f_bed.readline()
    if first_line:
        parts = first_line.strip().split('\t')
        if len(parts) >= 3:
            is_bed = True
        f_bed.seek(0)

    regions = {}
    names_list = set()
    if is_bed:
        regions = load_bed(f_bed)
    else:
        for line in f_bed:
            if line.strip():
                names_list.add(line.strip())

    for name, seq, qual in parse_seqs(f_in):
        chrom = name[1:].split()[0]
        if is_bed:
            if chrom in regions:
                for start, end, strand in regions[chrom]:
                    sub_seq = seq[start:end]
                    sub_qual = qual[start:end] if qual else ""
                    if strand_aware and strand == '-':
                        sub_seq = revcomp(sub_seq)
                        if sub_qual: sub_qual = sub_qual[::-1]

                    if tab_out:
                        print(f"{chrom}\t{start+1}\t{sub_seq}")
                    else:
                        new_name = f">{chrom}:{start+1}-{end}" if not qual else f"@{chrom}:{start+1}-{end}"
                        print(new_name)
                        if line_len > 0:
                            for i in range(0, len(sub_seq), line_len):
                                print(sub_seq[i:i+line_len])
                        else:
                            print(sub_seq)
                        if qual:
                            print("+")
                            if line_len > 0:
                                for i in range(0, len(sub_qual), line_len):
                                    print(sub_qual[i:i+line_len])
                            else:
                                print(sub_qual)
        else:
            if chrom in names_list:
                if tab_out:
                    print(f"{chrom}\t1\t{seq}")
                else:
                    print(name)
                    if line_len > 0:
                        for i in range(0, len(seq), line_len):
                            print(seq[i:i+line_len])
                    else:
                        print(seq)
                    if qual:
                        print("+")
                        if line_len > 0:
                            for i in range(0, len(qual), line_len):
                                print(qual[i:i+line_len])
                        else:
                            print(qual)

def cmd_sample(args_list):
    opts, args = get_args(args_list, "s:2")
    seed = 11
    two_pass = False
    for o, a in opts:
        if o == '-s': seed = int(a)
        elif o == '-2': two_pass = True

    if len(args) < 2: return
    f_in = open(args[0], 'r')
    num_or_frac = float(args[1])
    is_frac = (num_or_frac <= 1.0 and '.' in args[1]) or num_or_frac < 1.0
    if not is_frac and num_or_frac == 1.0 and '.' not in args[1]:
        is_frac = False
        num_or_frac = int(num_or_frac)

    random.seed(seed)

    if is_frac:
        for name, seq, qual in parse_seqs(f_in):
            if random.random() < num_or_frac:
                print(name)
                print(seq)
                if qual:
                    print("+")
                    print(qual)
    else:
        k = int(num_or_frac)
        reservoir = []
        for i, (name, seq, qual) in enumerate(parse_seqs(f_in)):
            if i < k:
                reservoir.append((i, name, seq, qual))
            else:
                j = random.randint(0, i)
                if j < k:
                    reservoir[j] = (i, name, seq, qual)

        if two_pass:
            reservoir.sort(key=lambda x: x[0])

        for idx, name, seq, qual in reservoir:
            print(name)
            print(seq)
            if qual:
                print("+")
                print(qual)

def cmd_trimfq(args_list):
    opts, args = get_args(args_list, "q:l:b:e:L:Q")
    err_rate = 0.05
    max_trim_down = 30
    b_trim = 0
    e_trim = 0
    for o, a in opts:
        if o == '-q': err_rate = float(a)
        elif o == '-l': max_trim_down = int(a)
        elif o == '-b': b_trim = int(a)
        elif o == '-e': e_trim = int(a)

    if len(args) < 1: return
    f_in = open(args[0], 'r')
    for name, seq, qual in parse_seqs(f_in):
        if b_trim > 0 or e_trim > 0:
            seq = seq[b_trim : len(seq) - e_trim if e_trim > 0 else len(seq)]
            if qual:
                qual = qual[b_trim : len(qual) - e_trim if e_trim > 0 else len(qual)]
        else:
            if qual:
                max_score = 0
                current_score = 0
                start = 0
                max_start = 0
                max_end = -1
                for i in range(len(qual)):
                    q_val = ord(qual[i]) - 33
                    p_err = 10 ** (-q_val / 10.0)
                    score = err_rate - p_err
                    current_score += score
                    if current_score < 0:
                        current_score = 0
                        start = i + 1
                    if current_score > max_score:
                        max_score = current_score
                        max_start = start
                        max_end = i

                if max_end >= 0:
                    L = max_end - max_start + 1
                    if L < max_trim_down:
                        diff = max_trim_down - L
                        # try to expand left and right
                        left_exp = min(max_start, diff // 2)
                        right_exp = min(len(seq) - 1 - max_end, diff - left_exp)
                        left_exp = diff - right_exp # adjust
                        if left_exp > max_start: left_exp = max_start
                        max_start -= left_exp
                        max_end += right_exp
                    seq = seq[max_start : max_end + 1]
                    qual = qual[max_start : max_end + 1]

        print(name)
        print(seq)
        if qual:
            print("+")
            print(qual)

def cmd_telo(args_list):
    if len(args_list) < 1: return
    f_in = open(args_list[0], 'r')

    total_len = 0
    telo_len = 0

    for name, seq, qual in parse_seqs(f_in):
        chrom = name[1:].split()[0]
        length = len(seq)
        total_len += length

        matches = []
        for match in re.finditer(r'(TTAGGG|CCCTAA)+', seq, re.IGNORECASE):
            st = match.start()
            en = match.end()
            if en - st >= 300:
                print(f"{chrom}\t{st}\t{en}\t{length}")
                telo_len += (en - st)

    sys.stderr.write(f"{telo_len}\t{total_len}\n")

def main():
    if len(sys.argv) < 2:
        return
    cmd = sys.argv[1]
    args = sys.argv[2:]

    if cmd == "seq":
        cmd_seq(args)
    elif cmd == "subseq":
        cmd_subseq(args)
    elif cmd == "sample":
        cmd_sample(args)
    elif cmd == "trimfq":
        cmd_trimfq(args)
    elif cmd == "telo":
        cmd_telo(args)
    else:
        # fallback for unimplemented commands
        sys.exit(1)

if __name__ == "__main__":
    main()
